class BaseModel(_BaseModel):
    def fill_template(self, context: dict, raise_exceptions=False, api_client=None):
        for field_name, field_value in self.model_dump().items():
            if isinstance(field_value, (dict, list, str)):
                filled_value = fill_template(
                    field_value, raise_exceptions=raise_exceptions, api_client=api_client, **context
                )
                setattr(self, field_name, filled_value)


class AuthBase(BaseModel):
    type: str

    def apply_to_request(self, request: "Requester") -> None:
        raise NotImplementedError


class TokenAuthBase(AuthBase):
    """Base for token-based auth managed by TokenCache (fetch + cache + retry-on-401).

    The fetched token is exposed to request templates as `{token}`
    """

    url: str  # token endpoint; also used to derive the cache key

    def fetch_token(self) -> str:
        raise NotImplementedError

    def apply_to_request(self, request: "Requester") -> None:
        return None


class BearerAuth(TokenAuthBase):
    type: Literal["bearer"] = "bearer"
    method: Literal["GET", "POST", "PUT", "PATCH", "DELETE"]
    content_type: Literal["json", "form"] | None = None
    content: dict[str, Any] | None = None
    headers: dict[str, str] = Field(default_factory=dict)
    params: dict[str, Any] = Field(default_factory=dict)
    credential_key: str

    def fetch_token(self) -> str:
        """Fetch a bearer token via a plain credentials request."""
        logging.info(f"Fetching new token for {self.url}")

        with requests.Session() as auth_session:
            auth_session.headers.update(self.headers or {})

            request_args = {
                "method": self.method,
                "url": str(self.url),
                "params": self.params,
            }

            if self.content_type == "json":
                request_args["json"] = self.content
            else:
                request_args["data"] = self.content

            try:
                response = auth_session.request(**request_args, timeout=DEFAULT_TIMEOUT)

                if not response.ok:
                    logging.error(f"Auth request failed with {response.status_code}: {response.text}\n")
                    response.raise_for_status()

                auth_data = response.json()
                keys = self.credential_key.split(".")
                token = auth_data
                for key in keys:
                    token = token.get(key)
                    if token is None:
                        logging.error(f"Auth token not found at key '{self.credential_key}'\n")
                        raise ResolveVarError(self.credential_key, "Auth Response")

                logging.info(f"Successfully fetched new token for {self.url}")
                return token

            except (requests.RequestException, JSONDecodeError, ResolveVarError) as e:
                logging.error(f"Failed to fetch or parse auth token: {str(e)}")
                raise


class OAuth1Auth(AuthBase):
    """OAuth 1.0a Token-Based Authentication (e.g. NetSuite TBA).

    The Authorization header is signed per-request from the credentials and the request's URL + query params.
    """

    type: Literal["oauth1"]
    consumer_key: str
    consumer_secret: str
    token_key: str
    token_secret: str
    realm: str
    signature_method: Literal["HMAC-SHA256", "HMAC-SHA1"] = "HMAC-SHA256"

    @staticmethod
    def _percent_encode(s: Any) -> str:
        return quote(str(s), safe="")

    def build_authorization_header(self, method: str, url: str, query_params: dict | None) -> str:
        """Compute the OAuth 1.0a Authorization header for a single request.

        `realm` is excluded from the signature base string, it appears only in the final header
        """
        oauth_params = {
            "oauth_consumer_key": self.consumer_key,
            "oauth_token": self.token_key,
            "oauth_signature_method": self.signature_method,
            "oauth_timestamp": str(int(time.time())),
            "oauth_nonce": uuid.uuid4().hex,
            "oauth_version": "1.0",
        }

        all_params = {**oauth_params, **(query_params or {})}
        sorted_params = "&".join(
            f"{self._percent_encode(k)}={self._percent_encode(v)}" for k, v in sorted(all_params.items())
        )
        base_string = f"{method.upper()}&{self._percent_encode(url)}&{self._percent_encode(sorted_params)}"
        signing_key = f"{self._percent_encode(self.consumer_secret)}&{self._percent_encode(self.token_secret)}"

        hash_mod = hashlib.sha256 if self.signature_method == "HMAC-SHA256" else hashlib.sha1
        signature = base64.b64encode(hmac.new(signing_key.encode(), base_string.encode(), hash_mod).digest()).decode()
        oauth_params["oauth_signature"] = signature

        header_params = {**oauth_params, "realm": self.realm}
        return "OAuth " + ", ".join(
            f'{self._percent_encode(k)}="{self._percent_encode(v)}"' for k, v in sorted(header_params.items())
        )

    def apply_to_request(self, request: "Requester") -> None:
        header = self.build_authorization_header(
            method=request.method,
            url=str(request.url),
            query_params=request.params,
        )
        request.headers = {**(request.headers or {}), "Authorization": header}


# =============================================================================
# Dependency-free RSA JWT signing (RS*/PS*) — used by OAuth2PrivateCertificateAuth.
# RSA signing is just modular exponentiation (pow(m, d, n)), so no external crypto
# library is required for unencrypted RSA keys — only the standard library.
# =============================================================================

_JWT_RSA_HASH = {
    "RS256": "sha256",
    "RS384": "sha384",
    "RS512": "sha512",
    "PS256": "sha256",
    "PS384": "sha384",
    "PS512": "sha512",
}
# ASN.1 DigestInfo prefixes for EMSA-PKCS1-v1_5 (RFC 8017).
_DIGEST_INFO_PREFIX = {
    "sha256": bytes.fromhex("3031300d060960864801650304020105000420"),
    "sha384": bytes.fromhex("3041300d060960864801650304020205000430"),
    "sha512": bytes.fromhex("3051300d060960864801650304020305000440"),
}


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _pem_to_der(pem: str) -> bytes:
    body = "".join(line.strip() for line in pem.strip().splitlines() if not line.startswith("-----"))
    return base64.b64decode(body)


def _read_der_tlv(data: bytes, offset: int) -> tuple[int, bytes, int]:
    """Read one ASN.1 DER tag-length-value triple; returns (tag, value, next_offset)."""
    tag = data[offset]
    offset += 1
    length = data[offset]
    offset += 1
    if length & 0x80:
        num_bytes = length & 0x7F
        length = int.from_bytes(data[offset : offset + num_bytes], "big")
        offset += num_bytes
    value = data[offset : offset + length]
    return tag, value, offset + length


def _der_sequence_integers(seq: bytes) -> list[int]:
    integers = []
    i = 0
    while i < len(seq):
        _, value, i = _read_der_tlv(seq, i)
        integers.append(int.from_bytes(value, "big"))
    return integers


def _rsa_modulus_and_private_exponent(pem: str) -> tuple[int, int]:
    """Extract (n, d) from an unencrypted PKCS#1 or PKCS#8 RSA private key PEM."""
    header_line = pem.strip().splitlines()[0]
    if "ENCRYPTED" in header_line or "Proc-Type" in pem:
        raise ValueError("encrypted private keys are not supported by the built-in signer")

    der = _pem_to_der(pem)
    _, sequence, _ = _read_der_tlv(der, 0)  # outer SEQUENCE

    if "BEGIN RSA PRIVATE KEY" in header_line:  # PKCS#1: RSAPrivateKey
        ints = _der_sequence_integers(sequence)
    else:  # PKCS#8: SEQUENCE { version, algorithm, privateKey OCTET STRING(RSAPrivateKey) }
        i = 0
        _, _, i = _read_der_tlv(sequence, i)  # version
        _, _, i = _read_der_tlv(sequence, i)  # algorithm identifier
        _, private_key, i = _read_der_tlv(sequence, i)  # privateKey OCTET STRING
        _, inner_seq, _ = _read_der_tlv(private_key, 0)
        ints = _der_sequence_integers(inner_seq)

    # RSAPrivateKey ::= { version, modulus(n), publicExponent(e), privateExponent(d), ... }
    return ints[1], ints[3]


def _mgf1(seed: bytes, length: int, hash_name: str) -> bytes:
    output = b""
    counter = 0
    while len(output) < length:
        output += hashlib.new(hash_name, seed + counter.to_bytes(4, "big")).digest()
        counter += 1
    return output[:length]


def _emsa_pkcs1_v15(message: bytes, hash_name: str, em_len: int) -> bytes:
    digest_info = _DIGEST_INFO_PREFIX[hash_name] + hashlib.new(hash_name, message).digest()
    if em_len < len(digest_info) + 11:
        raise ValueError("RSA key too small for the chosen hash")
    padding = b"\xff" * (em_len - len(digest_info) - 3)
    return b"\x00\x01" + padding + b"\x00" + digest_info


def _emsa_pss_encode(message: bytes, em_bits: int, hash_name: str, salt: bytes) -> bytes:
    m_hash = hashlib.new(hash_name, message).digest()
    h_len, s_len = len(m_hash), len(salt)
    em_len = (em_bits + 7) // 8
    if em_len < h_len + s_len + 2:
        raise ValueError("RSA key too small for RSA-PSS with the chosen hash")
    h = hashlib.new(hash_name, b"\x00" * 8 + m_hash + salt).digest()
    db = b"\x00" * (em_len - s_len - h_len - 2) + b"\x01" + salt
    masked_db = bytearray(a ^ b for a, b in zip(db, _mgf1(h, em_len - h_len - 1, hash_name)))
    masked_db[0] &= 0xFF >> (8 * em_len - em_bits)
    return bytes(masked_db) + h + b"\xbc"


def _sign_rsa_jwt(claims: dict, extra_header: dict, algorithm: str, private_key_pem: str) -> str:
    """Sign a JWT with an unencrypted RSA private key using only the standard library."""
    if algorithm not in _JWT_RSA_HASH:
        raise ValueError(f"Unsupported RSA JWT algorithm: {algorithm}")

    header = {"typ": "JWT", "alg": algorithm, **extra_header}
    signing_input = (
        _b64url(json.dumps(header, separators=(",", ":")).encode())
        + "."
        + _b64url(json.dumps(claims, separators=(",", ":")).encode())
    )

    n, d = _rsa_modulus_and_private_exponent(private_key_pem)
    hash_name = _JWT_RSA_HASH[algorithm]
    key_len = (n.bit_length() + 7) // 8

    if algorithm.startswith("RS"):  # EMSA-PKCS1-v1_5
        encoded = _emsa_pkcs1_v15(signing_input.encode("ascii"), hash_name, key_len)
    else:  # PS* (RSA-PSS); salt length == hash length per RFC 7518
        salt = os.urandom(hashlib.new(hash_name).digest_size)
        encoded = _emsa_pss_encode(signing_input.encode("ascii"), n.bit_length() - 1, hash_name, salt)

    signature = pow(int.from_bytes(encoded, "big"), d, n).to_bytes(key_len, "big")
    return signing_input + "." + _b64url(signature)


class OAuth2PrivateCertificateAuth(TokenAuthBase):
    """NetSuite OAuth 2.0 client credentials flow with a signed JWT client assertion.

    A JWT is signed with the integration's private certificate and exchanged at the token
    endpoint for a bearer access token. The token is cached and retried on 401 like any other
    token-based auth (via TokenCache), and is exposed to the request template as `{token}`.

    """

    type: Literal["oauth2_private_certificate"]
    client_id: str  # integration Client ID / Consumer Key -> JWT `iss`
    certificate_id: str  # NetSuite certificate id -> JWT header `kid`
    # Unencrypted RSA private key in PEM (PKCS#1 or PKCS#8), e.g. "{payload.secrets.private_certificate}".
    # Passphrase-protected/encrypted keys are NOT supported (the built-in signer needs no crypto deps).
    private_certificate: str
    scope: list[str] | str = Field(default_factory=lambda: ["rest_webservices"])
    signature_algorithm: Literal["PS256", "PS384", "PS512", "RS256", "RS384", "RS512"] = "PS256"
    assertion_expiry: int = 3600  # JWT lifetime in seconds (NetSuite maximum: 3600)
    credential_key: str = "access_token"
    # The following default to the NetSuite/JWT-bearer standard values but are exposed so other
    # providers (or non-standard setups) can override them instead of relying on the static defaults.
    audience: str | None = None  # JWT `aud` claim; defaults to the token endpoint `url` if omitted
    grant_type: str = "client_credentials"
    client_assertion_type: str = "urn:ietf:params:oauth:client-assertion-type:jwt-bearer"
    # Extra JWT payload claims (e.g. `jti`) merged in last, so they can also override the defaults above
    additional_claims: dict[str, Any] = Field(default_factory=dict)
    # Extra token-endpoint request body params merged in last
    additional_token_params: dict[str, Any] = Field(default_factory=dict)

    def _build_client_assertion(self) -> str:
        """Build and sign the JWT client assertion with the (unencrypted RSA) private certificate."""
        now = int(time.time())
        claims = {
            "iss": self.client_id,
            "scope": self.scope,
            "aud": self.audience or str(self.url),
            "iat": now,
            "exp": now + self.assertion_expiry,
            **self.additional_claims,
        }
        header = {"kid": self.certificate_id}
        return _sign_rsa_jwt(claims, header, self.signature_algorithm, self.private_certificate)

    def fetch_token(self) -> str:
        """Exchange the signed JWT assertion for a bearer access token."""
        logging.info(f"Fetching OAuth2 token (private certificate) for {self.url}")

        data = {
            "grant_type": self.grant_type,
            "client_assertion_type": self.client_assertion_type,
            "client_assertion": self._build_client_assertion(),
            **self.additional_token_params,
        }

        with requests.Session() as auth_session:
            try:
                response = auth_session.post(
                    str(self.url),
                    data=data,
                    headers={"Content-Type": "application/x-www-form-urlencoded"},
                    timeout=DEFAULT_TIMEOUT,
                )

                if not response.ok:
                    logging.error(f"OAuth2 token request failed with {response.status_code}: {response.text}\n")
                    response.raise_for_status()

                auth_data = response.json()
                keys = self.credential_key.split(".")
                token = auth_data
                for key in keys:
                    token = token.get(key) if isinstance(token, dict) else None
                    if token is None:
                        logging.error(f"OAuth2 access token not found at key '{self.credential_key}'\n")
                        raise ResolveVarError(self.credential_key, "OAuth2 Token Response")

                logging.info(f"Successfully fetched OAuth2 token for {self.url}")
                return token

            except (requests.RequestException, JSONDecodeError, ResolveVarError) as e:
                logging.error(f"Failed to fetch or parse OAuth2 token: {str(e)}")
                raise


class Requester(BaseModel):
    url: str
    method: Literal["GET", "POST", "PUT", "PATCH", "DELETE"]
    content: Any | None = None
    content_type: Literal["json", "form", "files", "multipart"] | None = None
    headers: dict[str, str] | None = None
    params: dict[str, Any] | None = None
    iterate_over: str | None = None
    iteration_item_name: str = "item"
    timeout: int = DEFAULT_TIMEOUT
    ignore_timeout: bool = False

    def execute(self, session: requests.Session, content_batch) -> requests.Response:
        session.headers.update(self.headers or {})
        request_kwargs = {"method": self.method, "url": str(self.url)}
        if self.params:
            request_kwargs["params"] = self.params
        if self.content_type == "json":
            request_kwargs["json"] = content_batch
        elif self.content_type == "files":
            request_kwargs["files"] = content_batch
        elif self.content_type == "multipart":
            files = {}
            data = {}
            if isinstance(content_batch, dict):
                for key, value in content_batch.items():
                    if isinstance(value, (list, tuple)):
                        files[key] = value
                    else:
                        data[key] = value
            else:
                files = content_batch

            request_kwargs["files"] = files
            if data:
                request_kwargs["data"] = data
        else:
            request_kwargs["data"] = content_batch
        request_kwargs["timeout"] = self.timeout
        response = session.request(**request_kwargs)
        logging.info(f"{self.method} API call to {self.url} returned status code {response.status_code}\n")
        return response


class ValueExtractor(BaseModel):
    """Defines how to extract a value from response using one operator."""

    jmespath: str | None = Field(None, alias="$jmespath")
    xmlpath: str | None = Field(None, alias="$xmlpath")
    regex: str | None = Field(None, alias="$regex")

    def model_post_init(self, __context):
        operators = [self.jmespath, self.xmlpath, self.regex]
        if sum(op is not None for op in operators) != 1:
            raise ValueError("Exactly one operator ($jmespath, $xmlpath, or $regex) must be specified")


class ValueConfig(BaseModel):
    """Maps a context path to an extraction operator. e.g., {"response.body": {"$jmespath": "key"}}"""

    model_config = ConfigDict(extra="forbid")

    context_path: str
    extractor: ValueExtractor

    @model_validator(mode="before")
    @classmethod
    def parse_value_config(cls, data: Any) -> dict:
        if isinstance(data, dict) and "context_path" not in data:
            # Shorthand format: {"response.body": {"$jmespath": "key"}}
            if len(data) != 1:
                raise ValueError("value config must contain exactly one context path")
            context_path, extractor_dict = next(iter(data.items()))
            return {"context_path": context_path, "extractor": extractor_dict}
        return data


class ResponseHandler(BaseModel):
    condition: dict[str, Any] | None = None  # condition to evaluate to decide if this handler is applicable
    target_type: Literal["schema_id", "document_relation", "property"]
    target_key: (
        str  # target schema id to store the response. If not resolvable, store as document relation with this key
    )
    value: ValueConfig | None = None

    def handle_response(
        self,
        api_call: "CallApiPhase",
        response: requests.Response,
        accessible_variables: "AccessibleVariables",
        sequence,
    ) -> bool:
        def response_to_dict(response: requests.Response) -> dict:
            normalized_headers = {k.replace("-", "_").lower(): v for k, v in response.headers.items()}

            return {
                "status_code": response.status_code,
                "headers": normalized_headers,
                "headers_raw": list(response.headers.items()),
                "text": response.text,
                "content": response.content,
                "url": response.url,
                "reason": response.reason,
                "elapsed": response.elapsed.total_seconds(),
                "ok": response.ok,
                "encoding": response.encoding,
                "cookies": dict(response.cookies),
            }

        content_type = response.headers.get("Content-Type", "unknown")
        context = {"response": response_to_dict(response)}
        found_value = None

        # Parse response body based on content type
        match content_type:
            case _ if "application/json" in content_type:
                body = response.json()
                context["response"]["body"] = body
                logging.info(f"Response content type is JSON for call api phase '{api_call.name}'\n")
            case _ if "xml" in content_type:
                xml_tree = ET.fromstring(response.text)
                context["response"]["body"] = response.text
                context["response"]["_xml_tree"] = xml_tree  # Store parsed tree for XPath
                logging.info(f"Response content type is XML for call api phase '{api_call.name}'\n")
            case _ if "text" in content_type:
                context["response"]["body"] = response.text
                logging.info(f"Response content type is Text for call api phase '{api_call.name}'\n")
            case _ if "unknown" in content_type:
                logging.info(f"Response content type is None (no body) for call api phase '{api_call.name}'\n")
            case _:
                body = response.content
                context["response"]["body"] = body
                logging.warning(
                    f"Response content type is unsupported ({content_type}) for call api phase '{api_call.name}'\n"
                )

        # Extract value using configured operator
        if self.value:
            # Get the target data from context
            path_parts = self.value.context_path.split(".")
            target_data = context
            for part in path_parts:
                target_data = target_data.get(part, {})

            # Apply the appropriate operator
            if self.value.extractor.jmespath:
                found_value = jmespath.search(self.value.extractor.jmespath, target_data)
                logging.info(
                    f"Applied JMESPath query '{self.value.extractor.jmespath}' on '{self.value.context_path}'\n"
                )

            elif self.value.extractor.xmlpath:
                if "_xml_tree" not in context["response"]:
                    raise ValueError("$xmlpath operator can only be used with XML responses")
                xml_tree = context["response"]["_xml_tree"]
                try:
                    xpath_result = xml_tree.findall(self.value.extractor.xmlpath)
                    if xpath_result:
                        if len(xpath_result) > 1:
                            found_value = [
                                elem.text if elem.text else ET.tostring(elem, encoding="unicode")
                                for elem in xpath_result
                            ]
                        else:
                            elem = xpath_result[0]
                            found_value = elem.text if elem.text else ET.tostring(elem, encoding="unicode")
                    else:
                        found_value = None
                    logging.info(f"Applied XPath query '{self.value.extractor.xmlpath}' on XML\n")
                except Exception as e:
                    logging.warning(f"XPath query '{self.value.extractor.xmlpath}' failed: {e}\n")
                    found_value = None

            elif self.value.extractor.regex:
                if not isinstance(target_data, str):
                    target_data = str(target_data)
                match_obj = re.search(self.value.extractor.regex, target_data)
                if match_obj:
                    try:
                        found_value = match_obj.group(1)
                    except IndexError:
                        found_value = match_obj.group(0)
                else:
                    found_value = None
                logging.info(f"Applied regex pattern '{self.value.extractor.regex}' on '{self.value.context_path}'\n")

            context["found_value"] = found_value

        if self.condition and check_condition(self.condition, context) is False:
            logging.info(f"Response handler condition not met for call api phase '{api_call.name}'\n")
            return False

        target_key = self.target_key.format(sequence=sequence)
        match self.target_type:
            case "schema_id":
                if isinstance(found_value, dict):
                    found_value = json.dumps(found_value)
                accessible_variables.field_cache[target_key].append(found_value)
                setattr(accessible_variables.field, target_key, found_value)
                return True
            case "property":
                if accessible_variables.property_.get(target_key):
                    logging.warning(
                        f"Variable {found_value} overwritten the property.{target_key}, because you use the same key multiple times. Old value is deleted."
                    )
                accessible_variables.property_[target_key] = found_value
                return True
            case "document_relation":
                api_client: ApiClient = accessible_variables.api_client
                document = api_client.upload_document(f"{target_key}_response", response.text, "text/plain")
                api_client.create_or_update_relation(
                    document, accessible_variables.payload["annotation"], self.target_key
                )
                logging.info(
                    f"Response handling for call api phase '{api_call.name}' stored response as document and created document relation with key '{self.target_key}'\n"
                )
                return True

        return False


class CallApiPhase(BaseModel):
